import { DEFAULT_SETTINGS } from "./defaults";
import type { AssistantSettings, HistoryItem, StorageShape } from "./types";

const MAX_HISTORY = 120;
const HISTORY_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function pruneHistory(history: HistoryItem[]): HistoryItem[] {
  const cutoff = Date.now() - HISTORY_TTL_MS;
  return history
    .filter((item) => item.favorite || item.createdAt >= cutoff)
    .map((item) => ({
      ...item,
      selection: {
        ...item.selection,
        surroundingText: undefined
      }
    }))
    .slice(0, MAX_HISTORY);
}

export async function getStorage(): Promise<StorageShape> {
  const stored = await chrome.storage.sync.get(["settings"]);
  const local = await chrome.storage.local.get(["history", "providerSecrets"]);
  const settings = { ...DEFAULT_SETTINGS, ...(stored.settings as Partial<AssistantSettings> | undefined) };
  const providerSecrets = (local.providerSecrets as Record<string, { apiKey?: string; baseUrl?: string }> | undefined) ?? {};
  const secret = providerSecrets[settings.provider.provider] ?? {};
  return {
    settings: {
      ...settings,
      provider: {
        ...settings.provider,
        apiKey: secret.apiKey,
        baseUrl: secret.baseUrl ?? settings.provider.baseUrl
      }
    },
    history: pruneHistory((local.history as HistoryItem[] | undefined) ?? [])
  };
}

export async function getSettings(): Promise<AssistantSettings> {
  return (await getStorage()).settings;
}

export async function saveSettings(settings: AssistantSettings): Promise<void> {
  const local = await chrome.storage.local.get(["providerSecrets"]);
  const providerSecrets = (local.providerSecrets as Record<string, { apiKey?: string; baseUrl?: string }> | undefined) ?? {};
  providerSecrets[settings.provider.provider] = {
    apiKey: settings.provider.apiKey,
    baseUrl: settings.provider.baseUrl
  };
  const publicSettings: AssistantSettings = {
    ...settings,
    provider: {
      provider: settings.provider.provider,
      model: settings.provider.model
    }
  };
  await chrome.storage.local.set({ providerSecrets });
  await chrome.storage.sync.set({ settings: publicSettings });
}

export async function addHistoryItem(item: HistoryItem): Promise<void> {
  const { history } = await getStorage();
  const compactItem: HistoryItem = {
    ...item,
    selection: {
      ...item.selection,
      surroundingText: undefined,
      text: item.selection.text.slice(0, 2500)
    },
    result: item.result.slice(0, 6000)
  };
  await chrome.storage.local.set({ history: pruneHistory([compactItem, ...history]) });
}

export async function clearHistory(): Promise<void> {
  await chrome.storage.local.set({ history: [] });
}

export async function deleteHistoryItem(id: string): Promise<void> {
  const { history } = await getStorage();
  await chrome.storage.local.set({ history: history.filter((item) => item.id !== id) });
}

export async function toggleHistoryFavorite(id: string): Promise<HistoryItem[]> {
  const { history } = await getStorage();
  const next = history.map((item) => (item.id === id ? { ...item, favorite: !item.favorite } : item));
  await chrome.storage.local.set({ history: pruneHistory(next) });
  return next;
}
